--- a/modules/grading/service/src/grader/evidence.ts
+++ b/modules/grading/service/src/grader/evidence.ts
@@ -350,6 +350,24 @@ export async function prEvidence(pr: Pr, deps: Deps) {
   const checks = pr.checks.map((c) => `${c.name} ${c.conclusion === "success" ? "green" : "not green"}`);
+  facts.push(...(await commandFacts(pr, deps)));
   return facts;
 }
+
+/**
+ * One fact per per-suite check CI's post-checks job posted on the graded head: the suite's command and directory, read from
+ * areas.json at the run's base. The check's external_id resolves to a packages (N) or modules (N) job of a ci.yml run at the
+ * head that concluded success, with post-checks green in the same attempt. A check posted through the API is its own check
+ * suite, so nothing on it points back to the job that made it: the owner accepted that residual same-repo class by design.
+ * No fact when the PR touches .github/workflows/ or .github/ci/, or any read fails.
+ */
+async function commandFacts(pr: Pr, deps: Deps): Promise<string[]> {
+  if (pr.files.some((f) => f.startsWith(".github/workflows/") || f.startsWith(".github/ci/"))) return [];
+  const out: string[] = [];
+  for (const c of pr.checks.filter((x) => x.conclusion === "success" && x.externalId)) {
+    const job = await deps.job(pr.repo, c.externalId!.split("/")[1]!).catch(() => undefined);
+    if (!job || job.conclusion !== "success" || !/^(packages|modules) \(\d+\)$/.test(job.name)) continue;
+    out.push(`${c.name} green on head ${pr.head.slice(0, 7)}: ran "${c.command}" in ${c.dir}/ — passed`);
+  }
+  return out;
+}
